function renderOutputs(){let arr=[...state.outputs.values()].sort((a,b)=>OUTPUT_ORDER.indexOf(a.key)-OUTPUT_ORDER.indexOf(b.key));
 // badge: "n FILES · m IN LIBRARY" — a count, so neutral; green only once every database is built
 let savedN=arr.filter(o=>o.lib).length,allBuilt=STAGES.every(s=>state.stageStatus[s.id]==='done');if($('#outputCount')){$('#outputCount').textContent=arr.length?`${arr.length} FILE${arr.length===1?'':'S'}${savedN?` · ${savedN} IN LIBRARY`:''}`:'0 FILES';$('#outputCount').className='result-badge'+(arr.length&&allBuilt?' ok':'')}
 for(const s of STAGES){let rows=arr.filter(o=>o.stage===s.id),host=document.querySelector(`[data-db-files="${s.id}"]`);if(host){host.innerHTML=(rows.some(o=>o.stale)?'<div class="db-stale-note">Inputs updated since these files were built — they are from the previous build and can still be downloaded. Rebuild to refresh them.</div>':'')+groupRows(rows);host.classList.toggle('phf-lib-list',rows.length>0)}let meta=document.querySelector(`[data-db-meta="${s.id}"]`);if(meta)meta.textContent=rows.length?`· ${rows.length} file${rows.length===1?'':'s'}`:''}
 // top run-strip download buttons
 bindTopDownload('dlFull','dlFullSize','master-full',arr);bindTopDownload('dlOrder','dlOrderSize','master-order',arr)}
function bindTopDownload(btnId,szId,key,arr){let btn=$('#'+btnId),o=arr.find(x=>x.key===key);if(!btn)return;if(o){btn.hidden=false;btn.href=o.url;btn.download=o.name;btn.classList.toggle('is-stale',!!o.stale);btn.title=o.stale?'From the previous build — an input was updated since. Rebuild to refresh it.':'';let sz=$('#'+szId);if(sz)sz.textContent=pretty(o.blob.size)}else{btn.hidden=true;btn.classList.remove('is-stale')}}
