 let g=$(`#dbgroup-${id}`);if(g){let b=g.querySelector('.db-mini');if(b){let[c,t]=RUN_PILL[status]||RUN_PILL.waiting;b.className='db-mini '+c;b.textContent=t;if(status==='done'&&msg)b.title=msg}let st=g.querySelector('.db-group-status');if(st){st.textContent=msg||'';st.className='db-group-status '+({running:'running',done:'ok',error:'error'}[status]||'info');st.hidden=(status==='done'&&id!=='master')}let build=g.querySelector('.db-build');if(build){build.disabled=(status==='running');build.textContent=status==='running'?'Building…':build.dataset.label}}
