async function buildCh2(){if(!state.files.ch2||!state.files.soh)throw new Error('CH2 requires ParagonCare / CH2 Pricelist and CR666a Stock On Hand.');stageSet('ch2','running','Reading CH2 pricelist and current SOH…');let [sup,soh,bm]=await Promise.all([readSheets(state.files.ch2),readSheets(state.files.soh),brandMap()]),p=C.parseSupplierSheets(sup),rc=C.resolveCh2Columns(p.headers),cm=[['wholesale','Wholesale ex GST'],['rrp','RRP inc GST']].filter(x=>rc[x[0]]===undefined).map(x=>x[1]);if(cm.length)throw new Error(`CH2 pricelist: no ${cm.join(' / ')} column found — the CH2 database was not built.`);let pr=C.processSupplier(p.headers,p.rows,bm),en=C.addEnhanced(pr.headers,pr.rows),sp=C.parseSoh(soh[0]?.rows||[]),lk=C.buildSohLookup(sp.data),mg=C.augmentSoh(en.headers,en.rows,lk.lookup);if(state.files.box){let bp=C.parseBoxSheets(await readSheets(state.files.box,{blankrows:false})),bx=C.mergeBox(mg.headers,mg.rows,bp.headers,bp.rows);mg={headers:bx.headers,rows:bx.rows}}stageSet('ch2','running','Writing the CH2 files…');let pos=SL.ch2(mg.headers,mg.rows),mt=new Set(mg.headers.filter(h=>h.includes('BARCODE')));let [main,pdb]=await Promise.all([makeBasic('Supplier_Data',mg.headers,mg.rows,mt,true),makeBasic('IN_SUPPLIER_UPDATE',SUP_LAYOUT,pos,SUP_TEXT)]);let w1=await verifyBasic(main,'Supplier_Data',mg.headers,mg.rows,true),w2=await verifyBasic(pdb,'IN_SUPPLIER_UPDATE',SUP_LAYOUT,pos);let d=stamp();addOutput('ch2','ch2-main',`clean_ch2_data_${d}.xlsx`,main,`${mg.rows.length.toLocaleString()} rows · full CH2 set, every column`,w1);addOutput('ch2','ch2-db',`clean_ch2_data_pos_db_${d}.xlsx`,pdb,`${pos.length.toLocaleString()} rows · supplier layout A–P (for your scripts)`,w2);state.models.ch2={headers:mg.headers,rows:mg.rows};stageSet('ch2','done',`Complete — ${mg.rows.length.toLocaleString()} CH2 rows · 2 / 2 outputs ready${warnText(w1,w2)}.`)}
